parameters.jsonBody:
={{ {
  startUrls: $("Get Up To 80 Active Airlines").all().map(item => ({ url: item.json.policy_url })),
  extractionMode: "single",
  prompt: ""
} }}

={{ (() => {
  const text = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
  let d = {};
  try { d = JSON.parse(text); } catch (e) { d = {}; }

  const source = $("Get All Apify Results").item.json;
  const confidenceRaw = Number(d.confidence);
  const scoreRaw = Number(d.surf_rating_score);

  return {
    p_policy_url: source.url ?? '',
    p_airline: d.airline_name ?? null,
    p_facts: {
      has_surfboard_policy: d.has_surfboard_policy === true,
      baggage_treatment: d.baggage_treatment ?? 'unclear',
      fee_text: d.fee_text ?? null,
      max_length_text: d.max_length_text ?? null,
      max_weight_text: d.max_weight_text ?? null,
      boards_per_bag_text: d.boards_per_bag_text ?? null,
      route_restrictions: d.route_restrictions ?? 'none stated',
      other_conditions: d.other_conditions ?? 'none stated'
    },
    p_confidence: Number.isFinite(confidenceRaw) ? Math.max(0, Math.min(1, confidenceRaw)) : 0,
    p_surfboard_treatment: d.surfboard_treatment ?? null,
    p_size_rule: d.size_rule ?? null,
    p_surf_rating_score: Number.isFinite(scoreRaw) ? Math.max(0, Math.min(5, Math.round(scoreRaw))) : null,
    p_surf_rating: d.surf_rating ?? null,
    p_notes: d.notes ?? 'Gemini returned no valid structured extraction.'
  };
})() }}

={{ {
  contents: [{
    role: "user",
    parts: [{
      text: `Extract the surfboard / surfing-equipment baggage policy from the airline page text below.

Use ONLY the supplied page text. Do not search the web. Do not invent missing facts.

Confidence measures how clearly the supplied page states the surfboard policy:
- 0.95–1.00: explicit and unambiguous
- 0.90–0.94: clear with minor ambiguity
- below 0.90: incomplete, unclear, conflicting, or not actually a surfboard policy

For surf_rating_score:
5 = exceptionally surf-friendly
4 = very good
3 = acceptable/moderate
2 = inconvenient/restrictive
1 = expensive/restrictive
0 = boards not accepted / exceptionally bad

PAGE URL:
${$json.url}

PAGE TEXT:
${$json.markdown}`
    }]
  }],
  generationConfig: {
    responseMimeType: "application/json",
    responseJsonSchema: {
      type: "object",
      properties: {
        airline_name: { type: ["string", "null"] },
        has_surfboard_policy: { type: "boolean" },
        baggage_treatment: {
          type: "string",
          enum: ["included", "normal_checked_bag", "special_fee", "not_accepted", "conditional", "unclear"]
        },
        fee_text: { type: ["string", "null"] },
        max_length_text: { type: ["string", "null"] },
        max_weight_text: { type: ["string", "null"] },
        boards_per_bag_text: { type: ["string", "null"] },
        route_restrictions: { type: "string" },
        other_conditions: { type: "string" },
        surfboard_treatment: { type: ["string", "null"] },
        size_rule: { type: ["string", "null"] },
        surf_rating_score: {
          type: ["integer", "null"],
          minimum: 0,
          maximum: 5
        },
        surf_rating: {
          type: ["string", "null"],
          enum: ["Excellent", "Very good", "Good", "Okay", "Bad", "Terrible", null]
        },
        confidence: {
          type: "number",
          minimum: 0,
          maximum: 1
        },
        notes: { type: "string" }
      },
      required: [
        "airline_name",
        "has_surfboard_policy",
        "baggage_treatment",
        "fee_text",
        "max_length_text",
        "max_weight_text",
        "boards_per_bag_text",
        "route_restrictions",
        "other_conditions",
        "surfboard_treatment",
        "size_rule",
        "surf_rating_score",
        "surf_rating",
        "confidence",
        "notes"
      ],
      additionalProperties: false
    }
  }
} }}
